  "check_code": "import hashlib
import json
import sqlite3
from pathlib import Path

from openpyxl import load_workbook


TARGET_ACTION = "TRA-2017-029"
TARGET_ACCOUNT = "EPT-SEC-001"
EVIDENCE_REF = "WFC-DIS-2017-006"
BASE_XLSX_HASH = "070aa89496ac67666a080977c934e7f6b3c1e4c321706cebc2b1b69058284518"
BASE_ACTIONS_HASH = "a93e818dc88b73e4ec840aebbf7f31a2e307c32b17c5130db4d634bebbd6bc38"
BASE_HISTORY_HASH = "b96736beb4b54e470b6d2cb40fe53048da7958ac4ab227d5040a186bff224082"


def _root(ws):
    return Path(ws)


def _db(ws):
    return _root(ws).resolve().parent / "system" / "treasury_remediation" / "state.db"


def _hash(value):
    return hashlib.sha256(json.dumps(value, default=str, sort_keys=True).encode()).hexdigest()


def _rows(con, sql, params=()):
    con.row_factory = sqlite3.Row
    return [dict(row) for row in con.execute(sql, params).fetchall()]


def check_remediation_post_state(ws):
    try:
        con = sqlite3.connect(f"file:{_db(ws)}?mode=ro", uri=True)
        actions = _rows(con, "SELECT * FROM remediation_actions WHERE action_type='SECURITIES_MANDATE_ALIGNMENT' AND account_id=? AND canonical_flag=1", (TARGET_ACCOUNT,))
        target = _rows(con, "SELECT * FROM remediation_actions WHERE action_id=?", (TARGET_ACTION,))
        events = _rows(con, "SELECT * FROM action_status_history WHERE action_id=? AND status_code='IN_PROGRESS' AND accepted_flag=1", (TARGET_ACTION,))
        if len(actions) != 1 or len(target) != 1:
            return {"score": 0, "detail": "Canonical securities action is missing or duplicated."}
        action = target[0]
        valid_events = [e for e in events if e["changed_by_person_id"] == action["owner_person_id"] and EVIDENCE_REF.lower() in e["change_comment"].lower()]
        if action["current_status"] != "IN_PROGRESS" or not valid_events:
            return {"score": 0, "detail": "Action is not In Progress with an accepted owner/event/evidence transition."}
        return {"score": 1, "detail": "Canonical action and accepted In Progress status event are aligned."}
    except Exception as exc:
        return {"score": 0, "detail": f"Remediation check error: {exc}"}
    finally:
        try:
            con.close()
        except Exception:
            pass


def check_tracker_alignment(ws):
    try:
        path = _root(ws) / "02_Control_Workpapers" / "Bank_Access_Remediation_Tracker_2025Q3.xlsx"
        wb = load_workbook(path, data_only=True, read_only=True)
        sheet = wb["Action_Register"]
        headers = [sheet.cell(4, col).value for col in range(1, sheet.max_column + 1)]
        account_col = headers.index("Account ID") + 1
        status_col = headers.index("Status") + 1
        target = None
        for row in range(5, sheet.max_row + 1):
            if str(sheet.cell(row, account_col).value).strip() == TARGET_ACCOUNT:
                target = [sheet.cell(row, col).value for col in range(1, sheet.max_column + 1)]
                break
        if target is None:
            return {"score": 0, "detail": "Securities tracker row is missing."}
        status = str(target[status_col - 1] or "").strip().lower().replace("-", " ")
        evidence_values = [str(value or "") for value in target]
        if status != "in progress" or not any(EVIDENCE_REF.lower() in value.lower() for value in evidence_values):
            return {"score": 0, "detail": "Securities tracker status or evidence reference is not aligned."}
        return {"score": 1, "detail": "Securities tracker row is aligned."}
    except Exception as exc:
        return {"score": 0, "detail": f"Tracker check error: {exc}"}


def check_unchanged_scope(ws):
    try:
        path = _root(ws) / "02_Control_Workpapers" / "Bank_Access_Remediation_Tracker_2025Q3.xlsx"
        wb = load_workbook(path, data_only=False, read_only=True)
        sheet = wb["Action_Register"]
        rows = []
        for row in range(1, sheet.max_row + 1):
            if row == 33:
                continue
            rows.append([sheet.cell(row, col).value for col in range(1, sheet.max_column + 1)])
        if _hash(rows) != BASE_XLSX_HASH:
            return {"score": 0, "detail": "A non-target tracker action row changed."}
        con = sqlite3.connect(f"file:{_db(ws)}?mode=ro", uri=True)
        actions = _rows(con, "SELECT * FROM remediation_actions WHERE action_id<>? ORDER BY action_id", (TARGET_ACTION,))
        history = _rows(con, "SELECT * FROM action_status_history WHERE action_id<>? ORDER BY status_history_id", (TARGET_ACTION,))
        if _hash(actions) != BASE_ACTIONS_HASH or _hash(history) != BASE_HISTORY_HASH:
            return {"score": 0, "detail": "A non-target remediation record changed."}
        return {"score": 1, "detail": "Non-target tracker and remediation records are unchanged."}
    except Exception as exc:
        return {"score": 0, "detail": f"Scope check error: {exc}"}
    finally:
        try:
            con.close()
        except Exception:
            pass
